function bestDigitSumPair(nums: number[]): number {
  const ds = nums.map(x => { let s = 0; while (x > 0) { s += x % 10; x = Math.floor(x / 10); } return s; });
  let best = -1;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j < nums.length; j++)
      if (ds[i] === ds[j]) best = Math.max(best, nums[i] + nums[j]);
  return best;
}

