function bestDigitSumPair(nums: number[]): number {
  const top = new Map<number, number>();
  let best = -1;
  for (const x of nums) {
    let s = 0;
    for (let v = x; v > 0; v = Math.floor(v / 10)) s += v % 10;
    const m = top.get(s);
    if (m !== undefined) {
      best = Math.max(best, m + x);
      if (x > m) top.set(s, x);
    } else top.set(s, x);
  }
  return best;
}

